"use strict";(globalThis.webpackChunkgrc||=[]).push([[16930],{26076(e){e.exports=JSON.parse('{"citeKey":"yang2015dominoes","slug":"yang-2015-dominoes-de0a","title":"Dominoes: Speculative Repair in Erasure Coded Hadoop System","authors":["X. Yang","C. Feng","Z. Xu","X.-H. Sun"],"venue":"22nd annual IEEE International Conference on High Performance Computing (HiPC 2015), Bengaluru, India","type":"Conference","entryType":"inproceedings","date":"December, 2015","year":2015,"era":"iit","month":12,"doi":"10.1109/hipc.2015.39","abstract":"Data volume grows dramatically in the era of big data. To save capital cost on storage hardware, datacenters currently prefer using erasure coding rather than simply replication to resist data loss. Erasure coding can provide equivalent three-way fault tolerance to HDFS\'s default three replication mechanism but degrades data availability for task scheduling. In an erasure-coded system, data reconstruction time will be paid while tasks access the missing blocks during MapReduce job processing. Tasks\' accessing corrupt data introduces task stragglers and degrades resource utilization. To overcome these challenges, we propose a novel mechanism, Dominoes, that coordinates lightweight data states checking and job scheduling to hide such recovery penalty during job processing and enhances job throughputs. The experimental results confirm Dominoes\' effectiveness and efficiency that improves job throughput by 9% to 9.7% under failure at an overhead of 2.6% for failure-free jobs.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2015/yang-2015-dominoes-de0a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["integrated-data-mgmt"],"memberAuthors":["sun-xian-he"]}')}}]);